krpano.action:
for(set(i,0), i LT 8, inc(i),
  if(i == 0, set(n,skin_btn_prev)); if(i == 1, set(n,skin_btn_next));
  if(i == 2, set(n,skin_btn_map)); if(i == 3, set(n,skin_btn_thumbs));
  if(i == 4, set(n,skin_btn_in)); if(i == 5, set(n,skin_btn_left));
  if(i == 6, set(n,skin_btn_right)); if(i == 7, set(n,skin_btn_up));
  set(layer[get(n)],visible=false,enabled=false);
);
set(layer[skin_btn_down],visible=false,enabled=false);
set(layer[skin_btn_out],visible=false,enabled=false);
set(layer[skin_btn_navi],visible=false,enabled=false);
set(layer[skin_btn_gyro],visible=true,align=center,x=-78,y=0,alpha=0.35);
copy(layer[skin_btn_gyro].enabled,plugin[skin_gyro].isavailable);
if(plugin[skin_gyro].isavailable, set(layer[skin_btn_gyro].alpha,1));
set(layer[skin_btn_fs],visible=true,align=center,x=-26,y=0,alpha=0.35);
copy(layer[skin_btn_fs].enabled,device.fullscreensupport);
if(device.fullscreensupport, set(layer[skin_btn_fs].alpha,1));
set(layer[skin_btn_vr],visible=true,align=center,x=26,y=0,alpha=0.35);
copy(layer[skin_btn_vr].enabled,webvr.isavailable);
if(webvr.isavailable, set(layer[skin_btn_vr].alpha,1));
set(layer[skin_btn_hide],visible=true,enabled=true,align=center,x=78,y=0);
